}

{
  "id": 6,
  "knowledge": "Investigation Intensity Index (III)",
  "description": "Combines behavioral and network analysis scores from an investigation.",
  "definition": "III = (0.6 \\times \\text{behansc}) + (0.4 \\times \\text{netansc})"
}

args.sql:
CREATE OR REPLACE FUNCTION check_premature_resolution()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    investigation_intensity numeric;
BEGIN
    IF NEW.resstat = 'Resolved' THEN
        SELECT 0.6 * id.behansc + 0.4 * id.netansc
        INTO investigation_intensity
        FROM investigationdetails AS id
        JOIN compliancecase AS cc ON id.compref = cc.compreg
        WHERE cc.compreg = NEW.compref2;

        IF investigation_intensity > 75.0 THEN
            RAISE EXCEPTION 'Premature Resolution Block: Investigation Intensity Index exceeds 75';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS premature_resolution_check ON enforcementactions;
CREATE TRIGGER premature_resolution_check
BEFORE UPDATE ON enforcementactions
FOR EACH ROW
EXECUTE FUNCTION check_premature_resolution();

